WITH flattened_attrs AS (SELECT id, log_ts, level, latency_ms, status_code, context, COALESCE(context['trace'], 'unknown') AS trace_or_default, context['region'] AS region FROM app_logs WHERE latency_ms <= 1581) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, DATE_TRUNC('HOUR', log_ts) AS hour_window, SIZE(COLLECT_SET(level)) AS num_levels, COUNT(CASE WHEN level = 'ERROR' THEN 1 END) AS error_count, SUM(latency_ms) FILTER (WHERE level = 'ERROR') AS error_total_latency_ms, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, SIZE(COLLECT_SET(level)) AS num_levels_2 FROM flattened_attrs GROUP BY 1, 2
